use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\EntityChangelog\EntityChangelogService;

class ClientIdentityWriteRepositoryAdapter implements ClientIdentityWriteGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly ClientIdentityPdoConnector $conn,
        private readonly EventDispatcherInterface $dispatcher,
        private readonly EntityChangelogService $changelog,
    ) {
    }
    #[Override]
    public function resolveForUpdate(ClientIdentityRef $ref): ?ClientIdentity
    {
        return $this->conn->retrieveForUpdate(new ClientIdentityFilter(uids: [ $ref->uid() ]));
    }
    #[Override]
    public function listForUpdate(?ClientIdentityFilter $filter = null, ?ClientIdentityCursor $cursor = null): ClientIdentitySlide
    {
        $this->logDebug("List for update of Client identity on adapter ");
        $span = $this->startSpan("List for update of Client identity on adapter");
        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new ClientIdentitySlide(function (ClientIdentitySlide $slide, ?ClientIdentityCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new ClientIdentityCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieveForUpdate(ClientIdentityFilter $filter): ?ClientIdentity
    {
        $this->logDebug("Retrieve for update of Client identity on adapter ");
        $span = $this->startSpan("Retrieve for update of Client identity on adapter");
        try {
            return $this->conn->retrieveForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function existsForUpdate(ClientIdentityFilter $filter): bool
    {
        $this->logDebug("Exists for update of Client identity on adapter ");
        $span = $this->startSpan("Exists for update of Client identity on adapter");
        try {
            return $this->conn->existsForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function countForUpdate(?ClientIdentityFilter $filter = null): int
    {
        $this->logDebug("Count for update of Client identity on adapter ");
        $span = $this->startSpan("Count for update of Client identity on adapter");
        try {
            return $this->conn->countForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function create(ClientIdentity $entity, ?Closure $verify = null): ClientIdentity
    {
        $this->logDebug("Count for Client identity on adapter ");
        $span = $this->startSpan("Count for Client identity on adapter");
        try {
            $created = $this->conn->create($entity, $verify);
            $this->dispatch($entity);
            $this->changelog->recordChange('client-identity', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $created;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(ClientIdentityRef $ref, ClientIdentity $entity): ClientIdentity
    {
        $this->logDebug("Count for Client identity on adapter ");
        $span = $this->startSpan("Count for Client identity on adapter");
        try {
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $this->changelog->recordChange('client-identity', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function delete(ClientIdentity $entity): bool
    {
        $this->logDebug("Count for Client identity on adapter ");
        $span = $this->startSpan("Count for Client identity on adapter");
        try {
            $result = $this->conn->delete($entity);
            $this->dispatch($entity);
            $this->changelog->recordDeletion('client-identity', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function findOneForUpdateByUid(string $uid): ?ClientIdentity
    {
        $this->logDebug("Find on by uid for Client identity on adapter");
        $span = $this->startSpan("Find on by uid for Client identity on adapter");
        try {
            return $this->conn->retrieveForUpdate(new ClientIdentityFilter(uids: [$uid]));
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function dispatch(ClientIdentity $entity): void
    {
        $this->logDebug("Count for Client identity on adapter ");
        $span = $this->startSpan("Count for Client identity on adapter");
        try {
            foreach ($entity->getTheEvents() as $event) {
                $this->dispatcher->dispatch($event);
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
